<main class="container"><div class="page-heading"><div><h1>Disponibilidad</h1><p>Selecciona turnos definidos por la universidad para cada materia ofertada.</p></div><a class="button secondary" href="<?= e(app_url('materias-ofertadas/')) ?>">Ver materias ofertadas</a></div>
<?php if ($message): ?><p class="success" role="status"><?= e($message) ?></p><?php endif; ?><?php if ($error): ?><p class="alert" role="alert"><?= e($error) ?></p><?php endif; ?>
<div class="table-wrapper card"><table><thead><tr><th>Materia</th><th>Periodo</th><th>Estado</th><th>Turnos permitidos</th></tr></thead><tbody><?php foreach ($subjects as $offer): ?><tr><td><?= e($offer['nombre_materia']) ?><span class="table-profile-description">Grupo <?= e($offer['nombre_grupo']) ?></span></td><td><?= e($offer['nombre_periodo']) ?><span class="table-profile-description"><?= e($offer['fecha_inicio']) ?> a <?= e($offer['fecha_fin']) ?></span></td><td><span class="status status-<?= e($offer['tutor_estado']) ?>"><?= e($offer['tutor_estado']) ?></span></td><td><?php if ($offer['tutor_estado'] === 'confirmada'): ?><form method="post" action="<?= e(app_url('tutor/mis_materias/horarios.php')) ?>"><input type="hidden" name="id_oferta_tutor" value="<?= (int) $offer['id_oferta_tutor'] ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><?php foreach ($offer['horarios_oferta'] as $schedule): ?><label class="checkbox-row"><input type="checkbox" name="id_oferta_horario[]" value="<?= (int) $schedule['id_oferta_horario'] ?>" <?= in_array((int) $schedule['id_oferta_horario'], array_map('intval', array_column($offer['horarios'], 'id_oferta_horario')), true) ? 'checked' : '' ?>><span><?= e($schedule['dia_semana'] . ' ' . $schedule['nombre_turno'] . ($schedule['nombre_aula'] ? ' | ' . $schedule['nombre_aula'] : '')) ?></span></label><?php endforeach; ?><?php if ($offer['horarios_oferta']): ?><button class="btn btn-sm btn-primary" type="submit">Guardar</button><?php else: ?><span class="table-muted">Sin turnos definidos.</span><?php endif; ?></form><?php else: ?><span class="table-muted">Solo disponible despues de la confirmacion.</span><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$subjects): ?><tr><td colspan="4">No tienes postulaciones a ofertas.</td></tr><?php endif; ?></tbody></table></div>
</main><?php require __DIR__ . '/../layouts/footer.php'; ?>
